'use strict';
const fighters=[
 {id:'birrow',name:'BIRROW',place:'Ocean Drive',style:'RITMO · VELOCIDADE',x:63,y:40,face:14.5},
 {id:'hector',name:'MEU PATRON',place:'Coral Gables',style:'KICKBOXING · GRAVES',x:34,y:39,face:38.2},
 {id:'halfred',name:'HALFRED',place:'Coral Way',style:'ENERGIA · ARRANCADA',x:38,y:34,face:61.8},
 {id:'cesar',name:'CESAR',place:'Coconut Grove',style:'ALCANCE · HARMONIA',x:41,y:48,face:85.3}
];
const $=id=>document.getElementById(id),music=window.arcadeAudio,reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
let state='studio',selected=0,playerIndex=null,pickStage='player',busy=false,introTimer;const cpuIndex=()=>pickStage==='opponent'?selected:(playerIndex===null?(selected===2?0:2):playerIndex);
const portraitFiles=['birrow-portrait.png','patron-portrait.png','halfred-portrait.png','cesar-portrait.png'];
const selectionStyle=document.createElement('style');selectionStyle.textContent='.card.selected:before{display:none}.card.player-lock:before{display:block;content:"1P";position:absolute;top:0;left:0;background:#42f7ff;color:#04172a;font-size:1.5cqw;font-weight:1000;padding:.1cqw .4cqw}.card.locked{opacity:.58;filter:saturate(.55)}.card.locked:hover{border-color:transparent}';document.head.append(selectionStyle);
function updateAudioLabel(){const s=music.status();$('sound').textContent=s.enabled?(s.context==='running'?'SOM: ON':'SOM: ATIVAR'):'SOM: OFF';$('sound').setAttribute('aria-pressed',String(s.enabled));}
async function unlock(){await music.unlock();updateAudioLabel();}
function effect(kind){unlock().then(()=>music.effect(kind));}
document.addEventListener('pointerdown',e=>{if(!e.target.closest('#sound'))unlock();},{capture:true});
document.addEventListener('keydown',()=>unlock(),{capture:true});
function transition(next){if(busy||next===state)return;busy=true;clearTimeout(introTimer);if(state==='fight'&&next!=='fight')window.fightEngine.stop();$('curtain').classList.add('closed');setTimeout(()=>{document.querySelectorAll('.screen').forEach(el=>el.hidden=el.id!==next);state=next;$('game').dataset.screen=next;music.setScene(next);$('curtain').classList.remove('closed');if(next==='select')render();if(next==='fight')window.fightEngine.start(fighters[playerIndex].id,fighters[selected].id);setTimeout(()=>{busy=false;if(next==='select')document.querySelector('.card.selected').focus({preventScroll:true});if(next==='ready')$('fight-now').focus({preventScroll:true});},reduced?0:460)},reduced?0:460)}
function render(){const player=fighters[playerIndex===null?selected:playerIndex],cpu=fighters[pickStage==='opponent'?selected:cpuIndex()],focus=fighters[selected],choosingOpponent=pickStage==='opponent';document.querySelector('.select-heading').textContent=choosingOpponent?'2/2 · ESCOLHA O ADVERSÁRIO':'1/2 · ESCOLHA SEU LUTADOR';$('fighter-name').textContent=player.name;$('cpu-name').textContent=choosingOpponent?cpu.name:'?';$('fighter-style').textContent=choosingOpponent?'CPU · '+focus.style:'SEU LUTADOR · '+focus.style;$('location-name').textContent=focus.place;const left=$('player-portrait');left.hidden=false;left.style.backgroundImage=`url('assets/${portraitFiles[playerIndex===null?selected:playerIndex]}')`;left.setAttribute('aria-label',player.name);const right=$('cpu-portrait');right.hidden=!choosingOpponent;if(choosingOpponent){right.style.backgroundImage=`url('assets/${portraitFiles[selected]}')`;right.setAttribute('aria-label',cpu.name)}document.querySelectorAll('.card').forEach((e,i)=>{const locked=choosingOpponent&&i===playerIndex;e.classList.toggle('selected',i===selected);e.classList.toggle('player-lock',choosingOpponent?i===playerIndex:i===selected);e.classList.toggle('cpu-target',choosingOpponent&&i===selected);e.classList.toggle('locked',locked);e.setAttribute('aria-pressed',String(i===selected));e.setAttribute('aria-disabled',String(locked));e.tabIndex=i===selected?0:-1});document.querySelectorAll('.pin').forEach((e,i)=>e.classList.toggle('active',i===selected));$('confirm').textContent=choosingOpponent?'ENTER · CONFIRMAR LUTA':'ENTER · ESCOLHER ADVERSÁRIO';$('live').textContent=choosingOpponent?'Escolha quem enfrentará '+player.name+'.':'Escolha qualquer um dos quatro lutadores.';}
function choose(i){if(busy)return;const next=(i+fighters.length)%fighters.length;if(pickStage==='opponent'&&next===playerIndex){$('live').textContent='A máquina precisa usar outro lutador.';effect('back');return}selected=next;render();effect('move');}
function confirm(){if(busy)return;if(pickStage==='player'){playerIndex=selected;pickStage='opponent';selected=(playerIndex+1)%fighters.length;render();effect('confirm');return}if(selected===playerIndex){effect('back');$('live').textContent='Escolha outro adversário.';return}const f=fighters[playerIndex],cpu=fighters[selected];$('ready-name').textContent=f.name;$('ready-cpu').textContent=cpu.name+' · CPU';$('ready-location').textContent=f.place;$('ready-copy').textContent=f.name+' enfrenta '+cpu.name+' na arena de '+f.place+'. Use os golpes básicos e complete POWER para liberar o especial com ALT + ESPAÇO.';$('fight-now').hidden=false;effect('confirm');transition('ready');}
fighters.forEach((f,i)=>{const b=document.createElement('button');b.className='card';b.setAttribute('aria-label',f.name+' — '+f.place);b.innerHTML='<span class="name">'+f.name+'</span>';b.onclick=()=>choose(i);$('roster').append(b);const p=document.createElement('button');p.className='pin';p.style.left=f.x+'%';p.style.top=f.y+'%';p.setAttribute('aria-label',f.place+' — selecionar '+f.name);p.innerHTML='<span>'+f.place+'</span>';p.onclick=()=>choose(i);$('pins').append(p)});
Promise.all(['studio','title','title-clean','select-clean','select','ocean-drive'].map(n=>new Promise(resolve=>{const im=new Image();im.onload=resolve;im.onerror=resolve;im.src='assets/'+n+'.png'}))).then(()=>{if(state==='studio'&&!busy)introTimer=setTimeout(()=>transition('title'),2800)});
$('skip').onclick=()=>{effect('open');transition('title')};$('start').onclick=()=>{playerIndex=null;pickStage='player';selected=0;effect('start');transition('select')};$('back').onclick=()=>{effect('back');transition('title')};$('confirm').onclick=confirm;$('fight-now').onclick=()=>{effect('start');transition('fight')};$('fight-pause').onclick=()=>window.fightEngine.togglePause();$('fight-exit').onclick=()=>{pickStage='player';playerIndex=null;selected=0;transition('select')};$('choose-again').onclick=()=>{pickStage='player';playerIndex=null;selected=0;effect('back');transition('select')};$('sound').onclick=async()=>{if(music.enabled&&music.status().context!=='running')await unlock();else await music.toggle();updateAudioLabel();if(music.enabled)music.effect('open')};
$('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{$('fullscreen').textContent='INDISPONÍVEL'}};
function openControls(){effect('open');$('controls-dialog').showModal();}function closeControls(){$('controls-dialog').close();effect('back');}
$('controls').onclick=openControls;$('view-controls').onclick=openControls;$('close-controls').onclick=closeControls;$('controls-dialog').addEventListener('cancel',()=>music.effect('back'));
 document.addEventListener('keydown',e=>{if(e.repeat||busy||$('controls-dialog').open)return;const key=e.key;if(state==='fight'&&key==='Escape'){e.preventDefault();pickStage='player';playerIndex=null;selected=0;transition('select');return}if(!['Enter','Escape','ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(key))return;if(key==='Enter'&&e.target.closest('button')&&!e.target.closest('.card'))return;e.preventDefault();if(state==='studio'&&key==='Enter'){effect('open');transition('title')}else if(state==='title'&&key==='Enter'){playerIndex=null;pickStage='player';selected=0;effect('start');transition('select')}else if(state==='select'){if(key.startsWith('Arrow')){choose(selected+(['ArrowLeft','ArrowUp'].includes(key)?-1:1));document.querySelector('.card.selected').focus({preventScroll:true})}if(key==='Enter')confirm();if(key==='Escape'){if(pickStage==='opponent'){pickStage='player';selected=playerIndex;render();effect('back')}else{effect('back');transition('title')}}}else if(state==='ready'){if(key==='Enter')transition('fight');if(key==='Escape'){effect('back');transition('select')}}});
render();$('game').dataset.screen=state;
window.arcadeDebug={getState:()=>({screen:state,selected:fighters[selected].name,cpu:fighters[cpuIndex()].name,arena:fighters[selected].place,busy,audio:music.status(),controlsOpen:$('controls-dialog').open,fight:window.fightEngine.status()})};
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'get_game_status',description:'Consulta tela, jogador, adversário da máquina, arena e estado do som.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>window.arcadeDebug.getState()})).catch(()=>{});}catch{}}
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'select_fighter',title:'Selecionar lutador',description:'Seleciona o lutador do jogador único. O adversário é a máquina; não inicia combate.',inputSchema:{type:'object',properties:{fighter:{type:'string',enum:fighters.map(f=>f.name)}},required:['fighter'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){const i=fighters.findIndex(f=>f.name===input?.fighter);if(i<0)throw new Error('Lutador inválido');if(state!=='select'||busy)throw new Error('Abra a seleção e aguarde a transição');choose(i);return{fighter:fighters[selected].name,arena:fighters[selected].place,cpu:fighters[cpuIndex()].name};}})).catch(()=>{});}catch{}}
